"use client";

import { Heart, Menu, Search, ShoppingBag } from "lucide-react";

type NavbarProps = {
  cartCount: number;
  favoriteCount: number;
  onMenu: () => void;
  onSearch: () => void;
  onCart: () => void;
  onWishlist: () => void;
};

export default function Navbar({ cartCount, favoriteCount, onMenu, onSearch, onCart, onWishlist }: NavbarProps) {
  return (
    <header className="site-header">
      <button className="icon-button menu-trigger" onClick={onMenu} aria-label="Ouvrir le menu"><Menu size={20} strokeWidth={1.5} /></button>
      <nav className="desktop-nav" aria-label="Navigation principale"><a href="#collections">Collections</a><a href="#histoire">Notre maison</a></nav>
      <a href="#top" className="wordmark">MAISON<span>®</span></a>
      <div className="header-actions">
        <button className="icon-button" aria-label="Rechercher" onClick={onSearch}><Search size={19} strokeWidth={1.5} /></button>
        <button className="icon-button count-button" aria-label={`Panier, ${cartCount} article${cartCount > 1 ? "s" : ""}`} onClick={onCart}><ShoppingBag size={19} strokeWidth={1.5} />{cartCount > 0 && <span>{cartCount}</span>}</button>
        <button className="icon-button" aria-label="Favoris" onClick={onWishlist}><Heart size={19} strokeWidth={1.5} />{favoriteCount > 0 && <span className="count-dot" />}</button>
      </div>
    </header>
  );
}
